class PaymentError(Exception):
    pass

def charge(card, amount):
    if not card.startswith('4'):
        raise PaymentError('card not accepted')
    if amount <= 0:
        raise ValueError('amount must be positive')
    return f'charged {amount}'

def checkout(card, amount):
    try:
